import{_ as t,o as r,c as o,a3 as n}from"./chunks/framework.BrO6lPIi.js";const u=JSON.parse('{"title":"多上下文通信机制","description":"本扩展采用 Manifest V3 双进程架构：Chrome 扩展端位于 `src/`，版本为 2.3.1；独立本地 Agent 端为 Node.js 服务，入口为 `agent/src/server.js`。","frontmatter":{"title":"多上下文通信机制","description":"本扩展采用 Manifest V3 双进程架构：Chrome 扩展端位于 `src/`，版本为 2.3.1；独立本地 Agent 端为 Node.js 服务，入口为 `agent/src/server.js`。"},"headers":[],"relativePath":"系统架构设计/Chrome-扩展核心架构/多上下文通信机制/index.md","filePath":"系统架构设计/Chrome-扩展核心架构/多上下文通信机制/index.md","lastUpdated":null}'),a={name:"系统架构设计/Chrome-扩展核心架构/多上下文通信机制/index.md"};function i(c,e,s,l,d,g){return r(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="多上下文通信机制" tabindex="-1">多上下文通信机制 <a class="header-anchor" href="#多上下文通信机制" aria-label="Permalink to &quot;多上下文通信机制&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js" target="_blank" rel="noreferrer">src/offscreen/offscreen.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html" target="_blank" rel="noreferrer">src/offscreen/offscreen.html</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js" target="_blank" rel="noreferrer">src/content/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/index.js" target="_blank" rel="noreferrer">src/side_panel/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/index.js" target="_blank" rel="noreferrer">src/options/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与上下文边界">项目结构与上下文边界</a></li><li><a href="#核心上下文职责划分">核心上下文职责划分</a></li><li><a href="#架构总览与权限模型">架构总览与权限模型</a></li><li><a href="#消息路由表设计模式">消息路由表设计模式</a></li><li><a href="#短消息与长连接选择策略">短消息与长连接选择策略</a></li><li><a href="#mv3-安全沙箱与剪贴板绕过方案">MV3 安全沙箱与剪贴板绕过方案</a></li><li><a href="#关键通信时序">关键通信时序</a></li><li><a href="#序列化大数据与安全验证">序列化、大数据与安全验证</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本扩展采用 Manifest V3 双进程架构：Chrome 扩展端位于 <code>src/</code>，版本为 2.3.1；独立本地 Agent 端为 Node.js 服务，入口为 <code>agent/src/server.js</code>。两者通过本地 HTTP/WebSocket 通信，但本文聚焦于 Chrome 扩展内部四个核心上下文的通信机制：<strong>Background Service Worker</strong>、<strong>Side Panel</strong>、<strong>Content Scripts</strong> 和 <strong>Offscreen Document</strong>。</p><p>在 MV3 中，Service Worker 生命周期受系统控制，空闲时可能被终止；Side Panel 是用户交互主界面；Content Script 注入网页执行页面级工具；Offscreen Document 则用于突破 MV3 对剪贴板等 API 的限制。这些上下文之间通过 <code>chrome.runtime.sendMessage</code>、<code>chrome.runtime.connect</code>、<code>chrome.tabs.sendMessage</code> 以及 Offscreen 文档的 <code>chrome.runtime.onMessage</code> 进行协作。</p><h2 id="项目结构与上下文边界" tabindex="-1">项目结构与上下文边界 <a class="header-anchor" href="#项目结构与上下文边界" aria-label="Permalink to &quot;项目结构与上下文边界&quot;">​</a></h2><p>扩展的上下文边界由 <code>manifest.json</code> 明确声明：</p><table tabindex="0"><thead><tr><th>上下文</th><th>入口或声明位置</th><th>主要职责</th></tr></thead><tbody><tr><td>Background Service Worker</td><td><code>manifest.json.background.service_worker</code> → <code>src/background/index.js</code></td><td>全局状态、消息路由、ReAct 执行循环、Agent 客户端、侧边栏控制、通知、定时任务</td></tr><tr><td>Side Panel</td><td><code>manifest.json.side_panel.default_path</code> → <code>side_panel.html</code> + <code>src/side_panel/index.js</code></td><td>聊天 UI、会话管理、工具面板、截图、导出、工作区、Agent 管理</td></tr><tr><td>Content Scripts</td><td><code>manifest.json.content_scripts</code> → <code>src/content/index.js</code></td><td>页面内容读取、DOM 交互、选区工具栏、区域截图、页面度量</td></tr><tr><td>Offscreen Document</td><td><code>manifest.json.permissions.offscreen</code> + <code>src/offscreen/offscreen.html</code></td><td>剪贴板读写（MV3 兼容桥）</td></tr><tr><td>Options Page</td><td><code>manifest.json.options_page</code> → <code>options.html</code> + <code>src/options/index.js</code></td><td>配置页、Agent 配对、工具箱、MCP/Skill/RAG 设置</td></tr></tbody></table><pre class="mermaid">graph TB
A[&quot;Side Panel&lt;br/&gt;src/side_panel/index.js&quot;] --&gt; B[&quot;Background Service Worker&lt;br/&gt;src/background/index.js&quot;]
C[&quot;Content Scripts&lt;br/&gt;src/content/index.js&quot;] --&gt; B
D[&quot;Options Page&lt;br/&gt;src/options/index.js&quot;] --&gt; B
B --&gt; E[&quot;Offscreen Document&lt;br/&gt;src/offscreen/offscreen.html&quot;]
B --&gt; F[&quot;Agent 本地服务&lt;br/&gt;agent/src/server.js&quot;]
B --&gt; G[&quot;IndexedDB / chrome.storage&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L20" target="_blank" rel="noreferrer">src/background/index.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L1-L34" target="_blank" rel="noreferrer">src/content/index.js#L1-L34</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li></ul><h2 id="核心上下文职责划分" tabindex="-1">核心上下文职责划分 <a class="header-anchor" href="#核心上下文职责划分" aria-label="Permalink to &quot;核心上下文职责划分&quot;">​</a></h2><h3 id="background-service-worker" tabindex="-1">Background Service Worker <a class="header-anchor" href="#background-service-worker" aria-label="Permalink to &quot;Background Service Worker&quot;">​</a></h3><p>Background 是扩展的核心调度层。它承担以下职责：</p><ol><li><strong>消息路由中心</strong>：统一接收 Side Panel、Content Script、Options Page 发来的 <code>chrome.runtime.sendMessage</code>，按 <code>message.type</code> 分发处理。</li><li><strong>ReAct 执行循环</strong>：协调工具预筛选、工具执行、流式输出、完成度校验、Token 统计。</li><li><strong>Side Panel 生命周期管理</strong>：打开/关闭侧边栏、脱离窗口、Tab 分组、作用域模式。</li><li><strong>Keepalive 长连接</strong>：通过 <code>chrome.runtime.connect</code> 建立命名端口，防止 SW 被系统回收。</li><li><strong>Agent 健康检查与心跳</strong>：定期检测本地 Agent 可达性，自动重连并刷新 MCP/RAG 工具。</li><li><strong>通知与可见性判定</strong>：根据焦点、面板状态、发起实例身份决定是否弹出桌面通知。</li><li><strong>Checkpoint 恢复</strong>：SW 被回收后通过闹钟唤醒，从 IndexedDB 恢复 ReAct 任务。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L20" target="_blank" rel="noreferrer">src/background/index.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L56-L95" target="_blank" rel="noreferrer">src/background/index.js#L56-L95</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L882-L918" target="_blank" rel="noreferrer">src/background/index.js#L882-L918</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L2005-L2307" target="_blank" rel="noreferrer">src/background/index.js#L2005-L2307</a></li></ul><h3 id="side-panel" tabindex="-1">Side Panel <a class="header-anchor" href="#side-panel" aria-label="Permalink to &quot;Side Panel&quot;">​</a></h3><p>Side Panel 是用户交互主界面，负责：</p><ol><li><strong>聊天与会话管理</strong>：发送消息、流式渲染、历史恢复、压缩摘要。</li><li><strong>工具面板与技能选择器</strong>：展示 MCP/Skill/RAG 工具，支持 @ 引用知识库。</li><li><strong>截图与图片识别</strong>：全屏截图、区域截图、图片附件。</li><li><strong>Agent 管理</strong>：配对、连接、重启、更新、停止。</li><li><strong>配置同步</strong>：监听 <code>chrome.storage.onChanged</code>，实时更新记忆限制、自动压缩等开关。</li><li><strong>与 Background 双向通信</strong>：通过 <code>sendMessage</code> 发起请求，通过 <code>connect</code> 维持长连接保活。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/index.js#L1-L34" target="_blank" rel="noreferrer">src/side_panel/index.js#L1-L34</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/index.js#L281-L298" target="_blank" rel="noreferrer">src/side_panel/index.js#L281-L298</a></li></ul><h3 id="content-scripts" tabindex="-1">Content Scripts <a class="header-anchor" href="#content-scripts" aria-label="Permalink to &quot;Content Scripts&quot;">​</a></h3><p>Content Script 注入所有匹配 URL，提供页面级能力：</p><ol><li><strong>消息路由表</strong>：使用 <code>HANDLERS</code> Map 实现 O(1) 查找，按 <code>message.type</code> 分发到具体处理器。</li><li><strong>页面读取</strong>：获取文本、HTML、选中内容、表格、元数据、链接、表单、图片。</li><li><strong>页面交互</strong>：点击元素、填写表单、滚动、键盘输入、文件上传。</li><li><strong>异步工具标记</strong>：通过 <code>ASYNC_HANDLERS</code> Set 判断是否需要保持消息通道开放。</li><li><strong>顶层帧保护</strong>：通过 <code>TOP_FRAME_ONLY_TYPES</code> 避免 iframe 响应覆盖主页面。</li><li><strong>区域截图选择</strong>：在页面创建遮罩层，让用户拖拽选择截图区域。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L195-L247" target="_blank" rel="noreferrer">src/content/index.js#L195-L247</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L267-L388" target="_blank" rel="noreferrer">src/content/index.js#L267-L388</a></li></ul><h3 id="offscreen-document" tabindex="-1">Offscreen Document <a class="header-anchor" href="#offscreen-document" aria-label="Permalink to &quot;Offscreen Document&quot;">​</a></h3><p>Offscreen Document 是 MV3 下剪贴板访问的专用上下文：</p><ol><li><strong>剪贴板读写桥</strong>：通过 <code>navigator.clipboard.writeText/readText</code> 实现复制粘贴。</li><li><strong>降级回退</strong>：当现代剪贴板 API 失败时，回退到 <code>document.execCommand(&#39;copy/paste&#39;)</code>。</li><li><strong>国际化文案</strong>：复用 <code>../shared/i18n.js</code> 的多语言支持。</li><li><strong>最小化 HTML</strong>：仅包含一个隐藏 textarea 作为剪贴板操作容器。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li></ul><h2 id="架构总览与权限模型" tabindex="-1">架构总览与权限模型 <a class="header-anchor" href="#架构总览与权限模型" aria-label="Permalink to &quot;架构总览与权限模型&quot;">​</a></h2><h3 id="上下文间通信架构图" tabindex="-1">上下文间通信架构图 <a class="header-anchor" href="#上下文间通信架构图" aria-label="Permalink to &quot;上下文间通信架构图&quot;">​</a></h3><pre class="mermaid">sequenceDiagram
participant SP as &quot;Side Panel&quot;
participant BG as &quot;Background Service Worker&quot;
participant CS as &quot;Content Script&quot;
participant OD as &quot;Offscreen Document&quot;
participant AG as &quot;Agent 本地服务&quot;
SP-&gt;&gt;BG : &quot;chrome.runtime.sendMessage(CALL_API)&quot;
BG-&gt;&gt;BG : &quot;工具预筛选 + ReAct 循环&quot;
BG-&gt;&gt;CS : &quot;chrome.tabs.sendMessage(页面工具)&quot;
CS--&gt;&gt;BG : &quot;页面结果&quot;
BG-&gt;&gt;OD : &quot;chrome.runtime.sendMessage(COPY_TO_CLIPBOARD)&quot;
OD--&gt;&gt;BG : &quot;剪贴板结果&quot;
BG-&gt;&gt;AG : &quot;HTTP/WebSocket 调用&quot;
AG--&gt;&gt;BG : &quot;工具执行结果&quot;
BG--&gt;&gt;SP : &quot;API_COMPLETE / STREAM_*&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1332-L1527" target="_blank" rel="noreferrer">src/background/index.js#L1332-L1527</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L91-L181" target="_blank" rel="noreferrer">src/content/index.js#L91-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h3 id="权限模型说明" tabindex="-1">权限模型说明 <a class="header-anchor" href="#权限模型说明" aria-label="Permalink to &quot;权限模型说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权限</th><th>用途</th><th>影响范围</th></tr></thead><tbody><tr><td><code>offscreen</code></td><td>创建 Offscreen Document</td><td>允许访问剪贴板等受限 API</td></tr><tr><td><code>clipboardRead</code></td><td>从剪贴板读取文本</td><td>通过 Offscreen Document 实现</td></tr><tr><td><code>clipboardWrite</code></td><td>写入剪贴板文本</td><td>通过 Offscreen Document 实现</td></tr><tr><td><code>sidePanel</code></td><td>打开/关闭侧边栏</td><td>控制 Side Panel 生命周期</td></tr><tr><td><code>scripting</code></td><td>动态注入脚本</td><td>配合 Content Script 使用</td></tr><tr><td><code>tabs</code></td><td>标签页操作</td><td>截图、消息转发、窗口管理</td></tr><tr><td><code>storage</code> / <code>unlimitedStorage</code></td><td>配置与持久化</td><td>Session、Checkpoint、Token 统计</td></tr><tr><td><code>debugger</code></td><td>调试功能</td><td>页面调试、CDP 操作</td></tr><tr><td><code>webNavigation</code></td><td>导航事件</td><td>页面加载状态监听</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li></ul><h2 id="消息路由表设计模式" tabindex="-1">消息路由表设计模式 <a class="header-anchor" href="#消息路由表设计模式" aria-label="Permalink to &quot;消息路由表设计模式&quot;">​</a></h2><h3 id="background-消息路由" tabindex="-1">Background 消息路由 <a class="header-anchor" href="#background-消息路由" aria-label="Permalink to &quot;Background 消息路由&quot;">​</a></h3><p>Background 使用 if-chain 方式按 <code>message.type</code> 分发消息，注释中明确列出了所有消息类型、来源和用途：</p><table tabindex="0"><thead><tr><th>消息类型</th><th>来源</th><th>用途</th><th>是否异步</th></tr></thead><tbody><tr><td><code>CANCEL_REACT</code></td><td>Side Panel</td><td>取消 ReAct 循环</td><td>否</td></tr><tr><td><code>TERMINATE_COMMAND</code></td><td>Side Panel</td><td>终止命令（不取消 ReAct）</td><td>否</td></tr><tr><td><code>RELOAD_MCP_TOOLS</code></td><td>Side Panel</td><td>强制重载 MCP 工具列表</td><td>是</td></tr><tr><td><code>RAG_SEARCH</code></td><td>Side Panel</td><td>知识库检索</td><td>是</td></tr><tr><td><code>GET_MCP_TOOLS</code></td><td>Side Panel</td><td>获取 MCP 工具（30s 缓存）</td><td>是</td></tr><tr><td><code>CAPTURE_TAB</code></td><td>Side Panel</td><td>截取可见标签页</td><td>是</td></tr><tr><td><code>CALL_API</code></td><td>Side Panel</td><td>主 API 调用入口</td><td>否（内部异步）</td></tr><tr><td><code>SELECTION_TOOLBAR_ACTION</code></td><td>Content Script</td><td>划词工具栏操作</td><td>否</td></tr><tr><td><code>FILL_SIDEPANEL_INPUT</code></td><td>Content Script</td><td>填充侧边栏输入框</td><td>否</td></tr><tr><td><code>DIRECT_SEND</code></td><td>Content Script</td><td>直接发送文本</td><td>否</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L882-L918" target="_blank" rel="noreferrer">src/background/index.js#L882-L918</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L920-L1980" target="_blank" rel="noreferrer">src/background/index.js#L920-L1980</a></li></ul><h3 id="content-script-消息路由" tabindex="-1">Content Script 消息路由 <a class="header-anchor" href="#content-script-消息路由" aria-label="Permalink to &quot;Content Script 消息路由&quot;">​</a></h3><p>Content Script 使用 <code>Map</code> 实现 O(1) 查找的消息路由表：</p><pre class="mermaid">flowchart TD
A[&quot;收到 chrome.runtime.onMessage&quot;] --&gt; B{&quot;message.type 是否存在于 HANDLERS?&quot;}
B --&gt; |否| C[&quot;忽略消息&quot;]
B --&gt; |是| D[&quot;调用对应处理器&quot;]
D --&gt; E{&quot;处理器返回 Promise 或属于 ASYNC_HANDLERS?&quot;}
E --&gt; |是| F[&quot;return true 保持通道开放&quot;]
E --&gt; |否| G[&quot;sendResponse 同步回复&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L209-L247" target="_blank" rel="noreferrer">src/content/index.js#L209-L247</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L209-L247" target="_blank" rel="noreferrer">src/content/index.js#L209-L247</a></li></ul><h2 id="短消息与长连接选择策略" tabindex="-1">短消息与长连接选择策略 <a class="header-anchor" href="#短消息与长连接选择策略" aria-label="Permalink to &quot;短消息与长连接选择策略&quot;">​</a></h2><h3 id="chrome-runtime-sendmessage-的使用场景" tabindex="-1">chrome.runtime.sendMessage 的使用场景 <a class="header-anchor" href="#chrome-runtime-sendmessage-的使用场景" aria-label="Permalink to &quot;chrome.runtime.sendMessage 的使用场景&quot;">​</a></h3><p><code>sendMessage</code> 适用于<strong>短消息、一次性请求-响应</strong>场景：</p><ol><li><strong>Side Panel → Background</strong>：<code>CALL_API</code>、<code>CAPTURE_TAB</code>、<code>GET_CHAT_CONFIG</code></li><li><strong>Content Script → Background</strong>：<code>SELECTION_TOOLBAR_ACTION</code>、<code>FILL_SIDEPANEL_INPUT</code>、<code>DIRECT_SEND</code></li><li><strong>Background → Offscreen</strong>：<code>COPY_TO_CLIPBOARD</code>、<code>PASTE_FROM_CLIPBOARD</code></li><li><strong>Background → Content Script</strong>：<code>SCREENSHOT_RESULT</code>、<code>STREAM_PRESELECT</code></li></ol><p>特点：</p><ul><li>单次请求，立即响应</li><li>最大消息大小 64MiB（Background 中对 executionLog 做了截断）</li><li>适合状态查询、工具调用、截图等</li></ul><h3 id="chrome-runtime-connect-的使用场景" tabindex="-1">chrome.runtime.connect 的使用场景 <a class="header-anchor" href="#chrome-runtime-connect-的使用场景" aria-label="Permalink to &quot;chrome.runtime.connect 的使用场景&quot;">​</a></h3><p><code>connect</code> 适用于<strong>长连接、双向通信、保活</strong>场景：</p><ol><li><strong>Side Panel → Background Keepalive</strong>：命名端口 <code>keepalive-{sessionId}</code></li><li><strong>身份上报</strong>：KEEPALIVE_IDENTITY 携带 windowId 和 hostTabId</li><li><strong>SW 重启检测</strong>：SW_RESTARTED 通知前端可恢复的 checkpoint</li><li><strong>面板断开提醒</strong>：延迟复核后触发桌面通知</li></ol><p>特点：</p><ul><li>持久连接，可多次 postMessage</li><li>防止 SW 被系统回收</li><li>适合长时间运行的任务（如 ReAct 循环）</li></ul><h3 id="选择策略总结" tabindex="-1">选择策略总结 <a class="header-anchor" href="#选择策略总结" aria-label="Permalink to &quot;选择策略总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐方式</th><th>原因</th></tr></thead><tbody><tr><td>一次性工具调用</td><td><code>sendMessage</code></td><td>简单、轻量、有超时</td></tr><tr><td>实时流式输出</td><td><code>sendMessage</code> + StreamController</td><td>分片传输，避免大消息</td></tr><tr><td>保活防回收</td><td><code>connect</code></td><td>长连接保持 SW 活跃</td></tr><tr><td>双向身份同步</td><td><code>connect</code></td><td>端口级别的状态共享</td></tr><tr><td>剪贴板操作</td><td><code>sendMessage</code> to Offscreen</td><td>隔离敏感 API</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L121-L218" target="_blank" rel="noreferrer">src/background/index.js#L121-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L97-L113" target="_blank" rel="noreferrer">src/background/index.js#L97-L113</a></li></ul><h2 id="mv3-安全沙箱与剪贴板绕过方案" tabindex="-1">MV3 安全沙箱与剪贴板绕过方案 <a class="header-anchor" href="#mv3-安全沙箱与剪贴板绕过方案" aria-label="Permalink to &quot;MV3 安全沙箱与剪贴板绕过方案&quot;">​</a></h2><h3 id="mv3-限制背景" tabindex="-1">MV3 限制背景 <a class="header-anchor" href="#mv3-限制背景" aria-label="Permalink to &quot;MV3 限制背景&quot;">​</a></h3><p>MV3 的 Service Worker 和 Content Script 无法直接访问某些浏览器 API，特别是剪贴板。这是出于安全考虑，防止恶意扩展随意读取用户剪贴板内容。</p><h3 id="offscreen-document-解决方案" tabindex="-1">Offscreen Document 解决方案 <a class="header-anchor" href="#offscreen-document-解决方案" aria-label="Permalink to &quot;Offscreen Document 解决方案&quot;">​</a></h3><p>项目通过 Offscreen Document 绕过限制：</p><ol><li><strong>权限声明</strong>：<code>manifest.json</code> 中声明 <code>offscreen</code>、<code>clipboardRead</code>、<code>clipboardWrite</code></li><li><strong>按需创建</strong>：Background 通过 <code>chrome.offscreen.createDocument</code> 按需创建 Offscreen 文档</li><li><strong>单例保护</strong>：通过 <code>creatingOffscreenDocument</code> Promise 避免重复创建</li><li><strong>剪贴板桥接</strong>：Offscreen 文档暴露 <code>COPY_TO_CLIPBOARD</code> 和 <code>PASTE_FROM_CLIPBOARD</code> 消息</li></ol><pre class="mermaid">sequenceDiagram
participant BG as &quot;Background&quot;
participant OD as &quot;Offscreen Document&quot;
participant CL as &quot;Clipboard API&quot;
BG-&gt;&gt;BG : &quot;ensureOffscreenDocument()&quot;
BG-&gt;&gt;OD : &quot;chrome.runtime.sendMessage(COPY_TO_CLIPBOARD)&quot;
OD-&gt;&gt;CL : &quot;navigator.clipboard.writeText()&quot;
CL--&gt;&gt;OD : &quot;成功/失败&quot;
OD--&gt;&gt;BG : &quot;{success, message/error}&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4883-L4901" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4883-L4901</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L41" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L41</a></li></ul><h3 id="降级策略" tabindex="-1">降级策略 <a class="header-anchor" href="#降级策略" aria-label="Permalink to &quot;降级策略&quot;">​</a></h3><p>当现代剪贴板 API 失败时，Offscreen 文档会回退到 <code>document.execCommand(&#39;copy/paste&#39;)</code>：</p><ol><li>创建一个隐藏的 textarea</li><li>设置值并 select()</li><li>调用 execCommand 执行复制/粘贴</li><li>清理临时元素</li></ol><p>这种双重策略确保在不同浏览器版本和环境下的兼容性。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L20-L22" target="_blank" rel="noreferrer">manifest.json#L20-L22</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4883-L4901" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4883-L4901</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h2 id="关键通信时序" tabindex="-1">关键通信时序 <a class="header-anchor" href="#关键通信时序" aria-label="Permalink to &quot;关键通信时序&quot;">​</a></h2><h3 id="call-api-完整流程" tabindex="-1">CALL_API 完整流程 <a class="header-anchor" href="#call-api-完整流程" aria-label="Permalink to &quot;CALL_API 完整流程&quot;">​</a></h3><pre class="mermaid">sequenceDiagram
participant SP as &quot;Side Panel&quot;
participant BG as &quot;Background&quot;
participant TS as &quot;Tool Executor&quot;
participant RL as &quot;React Loop&quot;
participant CS as &quot;Content Script&quot;
participant OD as &quot;Offscreen&quot;
participant AG as &quot;Agent&quot;
SP-&gt;&gt;BG : &quot;CALL_API(messages, model, useTools)&quot;
BG-&gt;&gt;BG : &quot;重置 API 调用计数&quot;
BG-&gt;&gt;TS : &quot;getTools(agentToolIds, agentId)&quot;
TS--&gt;&gt;BG : &quot;可用工具列表&quot;
BG-&gt;&gt;BG : &quot;工具预筛选&quot;
BG-&gt;&gt;RL : &quot;reactLoop(messages, tools, tabId)&quot;
loop ReAct 循环
RL-&gt;&gt;CS : &quot;chrome.tabs.sendMessage(页面工具)&quot;
CS--&gt;&gt;RL : &quot;页面操作结果&quot;
RL-&gt;&gt;OD : &quot;chrome.runtime.sendMessage(COPY_TO_CLIPBOARD)&quot;
OD--&gt;&gt;RL : &quot;剪贴板操作结果&quot;
RL-&gt;&gt;AG : &quot;HTTP/WebSocket 调用&quot;
AG--&gt;&gt;RL : &quot;AI 响应&quot;
RL-&gt;&gt;SP : &quot;STREAM_* 流式消息&quot;
end
RL--&gt;&gt;BG : &quot;最终结果&quot;
BG--&gt;&gt;SP : &quot;API_COMPLETE&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1332-L1527" target="_blank" rel="noreferrer">src/background/index.js#L1332-L1527</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L91-L181" target="_blank" rel="noreferrer">src/content/index.js#L91-L181</a></li></ul><h3 id="keepalive-保活流程" tabindex="-1">Keepalive 保活流程 <a class="header-anchor" href="#keepalive-保活流程" aria-label="Permalink to &quot;Keepalive 保活流程&quot;">​</a></h3><pre class="mermaid">sequenceDiagram
participant SP as &quot;Side Panel&quot;
participant BG as &quot;Background&quot;
participant SW as &quot;Service Worker&quot;
SP-&gt;&gt;BG : &quot;chrome.runtime.connect(&#39;keepalive-{sessionId}&#39;)&quot;
BG-&gt;&gt;BG : &quot;registerKeepalivePort(sessionId, port)&quot;
SP-&gt;&gt;BG : &quot;port.postMessage(KEEPALIVE_IDENTITY)&quot;
BG-&gt;&gt;BG : &quot;setKeepaliveIdentity(sessionId, identity)&quot;
BG--&gt;&gt;SP : &quot;HOST_TAB_RESOLVED(hostTabId)&quot;
Note over BG : &quot;SW 被回收前，连接断开&quot;
BG-&gt;&gt;BG : &quot;onDisconnect 延迟复核&quot;
BG-&gt;&gt;BG : &quot;shouldNotifyPanelDetached()&quot;
BG--&gt;&gt;SP : &quot;桌面通知如果面板确实关闭&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1332-L1527" target="_blank" rel="noreferrer">src/background/index.js#L1332-L1527</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li></ul><h2 id="序列化、大数据与安全验证" tabindex="-1">序列化、大数据与安全验证 <a class="header-anchor" href="#序列化、大数据与安全验证" aria-label="Permalink to &quot;序列化、大数据与安全验证&quot;">​</a></h2><h3 id="消息序列化限制" tabindex="-1">消息序列化限制 <a class="header-anchor" href="#消息序列化限制" aria-label="Permalink to &quot;消息序列化限制&quot;">​</a></h3><p>Chrome 扩展的消息传递基于结构化克隆算法，不支持函数、循环引用、undefined 等类型。Background 中对大消息的处理：</p><ol><li><strong>executionLog 截断</strong>：<code>truncateLogForMessage</code> 函数保留最后 1000 条日志，同时确保 <code>subtask_plan</code> 条目不被丢弃</li><li><strong>MAX_LOG_ENTRIES_FOR_MSG</strong>：常量定义最大日志条目数</li><li><strong>JSON.stringify 安全</strong>：所有跨上下文消息都经过 JSON 序列化</li></ol><h3 id="大数据传输优化" tabindex="-1">大数据传输优化 <a class="header-anchor" href="#大数据传输优化" aria-label="Permalink to &quot;大数据传输优化&quot;">​</a></h3><ol><li><strong>流式传输</strong>：ReAct 循环通过 <code>STREAM_*</code> 消息分片传输 AI 响应</li><li><strong>缓存机制</strong>：MCP 工具列表 30s 缓存，Skill Prompts 60s 缓存</li><li><strong>按需加载</strong>：Offscreen Document 按需创建，避免启动开销</li><li><strong>分页处理</strong>：Content Script 的页面交互工具支持 waitTime/timeout 参数</li></ol><h3 id="安全验证机制" tabindex="-1">安全验证机制 <a class="header-anchor" href="#安全验证机制" aria-label="Permalink to &quot;安全验证机制&quot;">​</a></h3><ol><li><strong>Source 校验</strong>：Content Script 中部分消息处理检查 <code>sender.tab?.id</code></li><li><strong>Frame 隔离</strong>：<code>TOP_FRAME_ONLY_TYPES</code> 防止 iframe 响应污染主页面</li><li><strong>权限最小化</strong>：Offscreen Document 仅暴露剪贴板相关消息</li><li><strong>错误降级</strong>：所有跨上下文调用都使用 <code>.catch()</code> 静默失败，避免扩展崩溃</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L97-L113" target="_blank" rel="noreferrer">src/background/index.js#L97-L113</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L195-L207" target="_blank" rel="noreferrer">src/content/index.js#L195-L207</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="常见问题与解决方案" tabindex="-1">常见问题与解决方案 <a class="header-anchor" href="#常见问题与解决方案" aria-label="Permalink to &quot;常见问题与解决方案&quot;">​</a></h3><h4 id="_1-service-worker-被回收导致消息丢失" tabindex="-1">1. Service Worker 被回收导致消息丢失 <a class="header-anchor" href="#_1-service-worker-被回收导致消息丢失" aria-label="Permalink to &quot;1. Service Worker 被回收导致消息丢失&quot;">​</a></h4><p><strong>现象</strong>：长时间运行任务后，Side Panel 无响应或显示“未连接”</p><p><strong>原因</strong>：MV3 Service Worker 空闲时被系统回收，内存中的 <code>activeReactLoops</code> 清空</p><p><strong>解决方案</strong>：</p><ul><li>使用 Keepalive 长连接防止回收</li><li>利用 Checkpoint 机制自动恢复任务</li><li>监听 <code>SW_RESTARTED</code> 消息提示用户继续执行</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L172-L197" target="_blank" rel="noreferrer">src/background/index.js#L172-L197</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L56-L81" target="_blank" rel="noreferrer">src/background/index.js#L56-L81</a></li></ul><h4 id="_2-侧边栏无法打开或关闭" tabindex="-1">2. 侧边栏无法打开或关闭 <a class="header-anchor" href="#_2-侧边栏无法打开或关闭" aria-label="Permalink to &quot;2. 侧边栏无法打开或关闭&quot;">​</a></h4><p><strong>现象</strong>：快捷键无效，或点击插件图标无反应</p><p><strong>原因</strong>：手势上下文丢失、Tab 分组状态异常、Chrome 版本兼容性问题</p><p><strong>解决方案</strong>：</p><ul><li>确保在用户手势同步栈内调用 <code>sidePanel.open()</code></li><li>检查 <code>_openPanelsByWindow</code> 镜像状态</li><li>使用 <code>bindSidePanelToTab</code> 绑定 Tab 专属面板</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L581-L789" target="_blank" rel="noreferrer">src/background/index.js#L581-L789</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L665-L747" target="_blank" rel="noreferrer">src/background/index.js#L665-L747</a></li></ul><h4 id="_3-剪贴板操作失败" tabindex="-1">3. 剪贴板操作失败 <a class="header-anchor" href="#_3-剪贴板操作失败" aria-label="Permalink to &quot;3. 剪贴板操作失败&quot;">​</a></h4><p><strong>现象</strong>：复制粘贴功能不可用</p><p><strong>原因</strong>：Offscreen Document 未创建、权限不足、浏览器 API 不支持</p><p><strong>解决方案</strong>：</p><ul><li>检查 <code>chrome.offscreen.createDocument</code> 是否成功</li><li>确认 manifest 中声明了 <code>offscreen</code>、<code>clipboardRead</code>、<code>clipboardWrite</code> 权限</li><li>查看 Offscreen 文档的控制台错误</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4883-L4901" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4883-L4901</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L20-L22" target="_blank" rel="noreferrer">manifest.json#L20-L22</a></li></ul><h4 id="_4-content-script-消息无响应" tabindex="-1">4. Content Script 消息无响应 <a class="header-anchor" href="#_4-content-script-消息无响应" aria-label="Permalink to &quot;4. Content Script 消息无响应&quot;">​</a></h4><p><strong>现象</strong>：Content Script 注册的消息处理器未被调用</p><p><strong>原因</strong>：消息类型不在 <code>HANDLERS</code> 中、iframe 响应冲突、扩展上下文失效</p><p><strong>解决方案</strong>：</p><ul><li>检查 <code>message.type</code> 是否在 <code>HANDLERS</code> 中定义</li><li>对于顶层帧独占操作，使用 <code>TOP_FRAME_ONLY_TYPES</code></li><li>监听 <code>Extension context invalidated</code> 错误</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L91-L181" target="_blank" rel="noreferrer">src/content/index.js#L91-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L249-L262" target="_blank" rel="noreferrer">src/content/index.js#L249-L262</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本项目实现了完整的 Chrome 扩展多上下文通信机制，通过精心设计的消息路由表、长连接保活策略和 Offscreen Document 权限绕过方案，解决了 MV3 架构下的核心挑战。</p><p>关键设计要点包括：</p><ol><li><strong>分层职责清晰</strong>：Background 负责调度和状态管理，Side Panel 专注 UI，Content Script 处理页面交互，Offscreen 隔离敏感 API</li><li><strong>O(1) 消息路由</strong>：使用 Map 实现高效的消息分发，支持异步处理器和顶层帧保护</li><li><strong>保活与恢复</strong>：Keepalive 长连接防止 SW 回收，Checkpoint 机制支持任务自动恢复</li><li><strong>权限最小化</strong>：Offscreen Document 仅暴露必要接口，降低安全风险</li><li><strong>容错设计</strong>：所有跨上下文调用都有错误处理和降级策略</li></ol><p>这套架构不仅满足了当前功能需求，也为未来的扩展提供了良好的基础。通过持续优化消息序列化、大数据传输和安全验证机制，可以进一步提升性能和安全性。</p>`,144)])])}const b=t(a,[["render",i]]);export{u as __pageData,b as default};
